CREATE TABLE "FreeDomainSuffix" ("id" SERIAL NOT NULL, "suffix" TEXT NOT NULL, "provider" TEXT NOT NULL, "enabled" BOOLEAN NOT NULL DEFAULT true, "prefix_pattern" TEXT NOT NULL DEFAULT '^[a-z][a-z0-9-]{2,15}$', "ttl" INTEGER NOT NULL DEFAULT 300, "quota_per_user" INTEGER NOT NULL DEFAULT 1, "reserved_words" TEXT NOT NULL DEFAULT '[]', "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "FreeDomainSuffix_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "FreeDomainSuffix_suffix_key" ON "FreeDomainSuffix"("suffix");
CREATE INDEX "FreeDomainSuffix_enabled_idx" ON "FreeDomainSuffix"("enabled");
CREATE INDEX "FreeDomainSuffix_provider_idx" ON "FreeDomainSuffix"("provider");
CREATE TABLE "ServerDomain" ("id" SERIAL NOT NULL, "server_id" INTEGER, "user_id" INTEGER NOT NULL, "suffix_id" INTEGER NOT NULL, "prefix" TEXT NOT NULL, "domain" TEXT NOT NULL, "target" TEXT NOT NULL, "port" INTEGER NOT NULL DEFAULT 25565, "application_status" TEXT NOT NULL DEFAULT 'PENDING_REVIEW', "dns_status" TEXT NOT NULL DEFAULT 'NOT_REQUESTED', "reviewed_at" TIMESTAMP(3), "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "ServerDomain_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "ServerDomain_server_id_key" ON "ServerDomain"("server_id");
