CREATE INDEX "ServerDomain_dns_status_idx" ON "ServerDomain"("dns_status");
CREATE TABLE "DnsRecord" ("id" SERIAL NOT NULL, "server_domain_id" INTEGER NOT NULL, "record_type" TEXT NOT NULL, "name" TEXT NOT NULL, "content" TEXT NOT NULL, "ttl" INTEGER NOT NULL, "provider_record_id" TEXT, "created_by_platform" BOOLEAN NOT NULL DEFAULT true, "status" TEXT NOT NULL DEFAULT 'PENDING', "last_error" TEXT, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "DnsRecord_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "DnsRecord_server_domain_id_record_type_name_content_key" ON "DnsRecord"("server_domain_id", "record_type", "name", "content");
