CREATE TABLE "DnsTask" ("id" SERIAL NOT NULL, "server_domain_id" INTEGER NOT NULL, "action" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'PENDING', "attempts" INTEGER NOT NULL DEFAULT 0, "next_attempt_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "locked_at" TIMESTAMP(3), "last_error" TEXT, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "DnsTask_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "DnsTask_server_domain_id_action_key" ON "DnsTask"("server_domain_id", "action");
CREATE INDEX "DnsTask_status_next_attempt_at_idx" ON "DnsTask"("status", "next_attempt_at");
ALTER TABLE "ServerDomain" ADD CONSTRAINT "ServerDomain_server_id_fkey" FOREIGN KEY ("server_id") REFERENCES "Server"("id") ON DELETE SET NULL ON UPDATE CASCADE;
